cases.input:
// @covers clean document: no issues from any stage
{
  id: "root",
  children: [
    { id: "a", ports: [ { id: "p" } ], labels: [ { id: "l", text: "A" } ] },
    { id: "b" }
  ],
  edges: [ { id: "e", sources: [ "p" ], targets: [ "b" ] } ]
}

// @covers numbers out of range or malformed for their converters
{
  id: "root",
  x: 1e999,
  y: 99999999999999999999,
  width: -1e999,
  height: 1.5,
  layoutOptions: { "org.example.big": 99999999999999999999, "org.example.huge": 1e999 }
}

// @covers empty property key (value converter: cannot convert empty string)
{
  id: "root",
  layoutOptions: { "": 1, ok: 2 }
}

// @covers property value forms: strings, numbers, booleans, single quotes
{
  id: "root",
  layoutOptions: {
    "org.example.s": 'single',
    "org.example.n": 1.5e3,
    "org.example.b": true,
    "org.eclipse.elk.direction": 'DOWN',
    "org.eclipse.elk.spacing.nodeNode": 12
  }
}

// @covers invalid string escapes and unicode in identifier and text values
{
  id: "bad \q escape",
  children: [ { id: "short \u12 unicode", labels: [ { id: "l", text: "bad \z" } ] } ],
  layoutOptions: { "org.example.k": "bad \y" }
}

// @covers duplicate node, port and label identifiers
{
  id: "root",
  children: [
    { id: "a", ports: [ { id: "p" }, { id: "p" } ], labels: [ { id: "l" }, { id: "l" } ] },
    { id: "a" }
  ]
}

// @covers duplicate property keys (same option twice, full id and suffix spelling) on one element
{
  id: "root",
  layoutOptions: {
    "org.eclipse.elk.direction": "DOWN",
    "org.eclipse.elk.direction": "UP",
    "org.example.custom": 1,
    "org.example.custom": 2
  },
  children: [ { id: "a", layoutOptions: { direction: "DOWN", "elk.direction": "UP", "org.eclipse.elk.direction": "LEFT" } } ]
}

// @covers the same property key on different elements: no collision
{
  id: "root",
  layoutOptions: { "org.eclipse.elk.direction": "DOWN" },
  children: [ { id: "a", layoutOptions: { "org.eclipse.elk.direction": "UP" } } ]
}

// @covers arbitrary JSON members the grammar accepts and ignores
{
  id: "root",
  custom: { nested: [ 1, "two", null, true, { deep: false } ] },
  "other": "y z",
  children: [ { id: "a", note: [ ] } ]
}

// @covers elements without an identifier (nodes, labels, edges)
{
  children: [ { }, { ports: [ { x: 1 } ] } ],
  labels: [ { text: "t" } ],
  edges: [ { sources: [ "a" ], targets: [ "b" ] } ]
}

// @covers invalid option values (enum, double, int, boolean): no LayoutOptionValidator for .elkj, so no issue
{
  id: "root",
  layoutOptions: {
    "org.eclipse.elk.direction": "bogus",
    "org.eclipse.elk.spacing.nodeNode": "abc",
    "org.eclipse.elk.padding": "not a padding",
    "org.eclipse.elk.interactive": "maybe"
  },
  children: [ { id: "a", layoutOptions: { "org.eclipse.elk.priority": "1.5x" } } ]
}

// @covers legacy de.cau.cs.kieler key, elk. prefix and bare suffix spellings of one option: collision recorded as the JVM reports it
{
  id: "root",
  layoutOptions: {
    "de.cau.cs.kieler.direction": "DOWN",
    "elk.direction": "UP",
    direction: "LEFT"
  }
}

// @covers unknown option keys and wrongly targeted options: no validator issue
{
  id: "root",
  layoutOptions: {
    "org.example.unknown": 1,
    unknownBare: "plain",
    "org.eclipse.elk.edge.thickness": 3,
    "org.eclipse.elk.port.side": "NORTH"
  }
}

// @covers reference to an identifier shared by two nodes (ambiguous or first-wins as recorded)
{
  id: "root",
  children: [ { id: "dup" }, { id: "dup" }, { id: "b" } ],
  edges: [ { id: "e", sources: [ "dup" ], targets: [ "b" ] } ]
}

// @covers edge source naming an edge (not a connectable shape)
{
  id: "root",
  children: [ { id: "a" } ],
  edges: [ { id: "e1", sources: [ "a" ], targets: [ "a" ] }, { id: "e2", sources: [ "e1" ], targets: [ "a" ] } ]
}

// @covers edge source and target naming a label (type mismatch through scoping)
{
  id: "root",
  children: [ { id: "a", labels: [ { id: "lbl", text: "t" } ] }, { id: "b" } ],
  edges: [
    { id: "e1", sources: [ "lbl" ], targets: [ "b" ] },
    { id: "e2", sources: [ "a" ], targets: [ "lbl" ] }
  ]
}

// @covers edges with empty or missing sources and targets lists
{
  id: "root",
  edges: [ { id: "e1", sources: [], targets: [] }, { id: "e2" } ]
}

// @covers references across hierarchy levels and to same-named ports of different nodes
{
  id: "root",
  children: [
    { id: "a", ports: [ { id: "p" } ], children: [ { id: "inner" } ] },
    { id: "b", ports: [ { id: "p" } ] }
  ],
  edges: [ { id: "e", sources: [ "inner" ], targets: [ "p" ] } ]
}

// @covers unresolved source and target references (lazy linking diagnostics, with lines and codes)
{
  id: "root",
  children: [ { id: "a" } ],
  edges: [
    { id: "e1", sources: [ "nowhere" ], targets: [ "a" ] },
    { id: "e2", sources: [ "a" ], targets: [ "missing" ] },
    { id: "e3", sources: [ "x1", "a", "x2" ], targets: [ "y1" ] }
  ]
}

// @covers linking diagnostic order across nested containers: root edge, child edge, child's child edge
{
  id: "root",
  edges: [ { id: "e0", sources: [ "r1" ], targets: [ "r2" ] } ],
  children: [
    { id: "a",
      edges: [ { id: "e1", sources: [ "a1" ], targets: [ "a2" ] } ],
      children: [ { id: "b", edges: [ { id: "e2", sources: [ "b1" ], targets: [ "b2" ] } ] } ] },
    { id: "c", edges: [ { id: "e3", sources: [ "c1" ], targets: [ "c2" ] } ] }
  ]
}

// @covers linking diagnostic order: targets written before sources, unresolved in several edges
{
  id: "root",
  children: [ { id: "a" } ],
  edges: [
    { id: "e1", targets: [ "t1" ], sources: [ "s1" ] },
    { id: "e2", targets: [ "a", "t2" ], sources: [ "s2", "a" ] },
    { id: "e3", sources: [ "s3" ], targets: [ "t3" ] }
  ]
}

// @covers syntax errors: stray token and missing colon (presence only)
{
  id: "root",
  children [ { id: "a" } ],
  @ bogus
}

// @covers quoted keyword strings lex as keywords, not STRING: a property value "text" or 'x' is a syntax error (presence only)
{
  id: "root",
  layoutOptions: { "org.example.a": "text", "org.example.b": 'x', "org.example.c": "children" }
}

// @covers syntax error: missing closing brace (presence only)
{
  id: "root",
  children: [ { id: "a" }

// @covers syntax error: unterminated string (presence only)
{
  id: "root",
  layoutOptions: { "org.example.k": "never closed }
}

// @covers property value that is null, an object or an array (not allowed by the Property rule)
{
  id: "root",
  layoutOptions: { "org.example.a": null, "org.example.b": { x: 1 }, "org.example.c": [ 1 ] }
}

// @covers known keys with the wrong value shape (presence only)
{
  id: "root",
  children: { id: "a" },
  x: "text",
  width: true
}
